INSERT INTO `cms_pages` (`id`, `slug`, `title`, `content_json`, `is_published`, `updated_at`) VALUES
(1, 'about-us', 'About Us', '{\"heroQuote\":\"\\\"Inspiring dressing up & undressing\\\"\",\"heroParagraphs\":[\"We are a luxury lingerie, ready-to-wear, and swim brand. Our name speaks to the unique duality of our spirit.\",\"We take a fashion approach to lingerie, and apply a lingerie language to fashion. Our products are delicate and sophisticated, using luxury fabrics and bespoke embroideries crafted by world-class artisans.\",\"We are constantly thinking about the emotion attached to lingerie, and our goal is to create products that make women of all ages and sizes feel their best.\"],\"heroImage\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562043\\/about_us\\/b1eorjbfkdjy9y63njj1.jpg\",\"fataleHashtag\":\"#underpure\",\"fataleImages\":[{\"id\":1784562074572,\"src\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562073\\/about_us\\/skxwy2t0k6odrssedvb0.jpg\",\"hasPlay\":false},{\"id\":1784562093105,\"src\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562092\\/about_us\\/dmsx0cgaxfmqo0r8fdwp.jpg\",\"hasPlay\":false},{\"id\":1784562108567,\"src\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562107\\/about_us\\/gw4ui90sxvsspct7vxv0.jpg\",\"hasPlay\":false}],\"designPhilosophyLabel\":\"DESIGN PHILOSOPHY\",\"designPhilosophyParagraphs\":[\"Our ready-to-wear and swim collections embody this same spirit. Lingerie-inspired pieces are tastefully provocative, while maintaining bold style and practical wearability.\",\"Our customer is comfortable embracing both her femininity and her confidence, knowing that these two qualities make her unstoppable.\"],\"philosophyImages\":[{\"id\":1784562141227,\"src\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562140\\/about_us\\/ta9wfkjegenksxsvidwn.png\"},{\"id\":1784562191823,\"src\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562190\\/about_us\\/waqjpcqhdnpwvahs5xwl.jpg\"},{\"id\":1784562206046,\"src\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562205\\/about_us\\/saochn4iipjvioiq482a.jpg\"},{\"id\":1784562223752,\"src\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784562223\\/about_us\\/d6b72cjtrevxcwkippob.png\"}]}', 1, '2026-09-24 10:14:01'),
(2, 'affiliates', 'Affiliates', '{\"heading\":\"become an affiliate\",\"enabledInFooter\":false,\"enabledInGetHelp\":false,\"columns\":[{\"title\":\"CREATOR AFFILIATES\",\"paragraphs\":[\"UnderPure is looking to connect with elevated creators that are focused on fashion, styling and trends.\",\"Build shoppable lists and share links to earn commission on every purchase. UnderPure offers 15% commission off of any direct sales & unique discount codes up to 10% to share with your audience.\",\"Use UnderPure\'s code, UNDERPURE-2025 when you sign up below.\"],\"buttons\":[{\"text\":\"SIGN UP ON SHOPMY\",\"url\":\"https:\\/\\/shopmy.us\"}]},{\"title\":\"PUBLISHING AFFILIATES\",\"paragraphs\":[\"UnderPure is looking for fashion-forward websites to join the UnderPure affiliate program.\",\"As a member of the program, you will earn a commission when visitors referred by you make a purchase on underpure.com\",\"Signup for approval via Rakuten Advertising below:\"],\"buttons\":[{\"text\":\"CONNECT ON RAKUTEN\",\"url\":\"https:\\/\\/rakutenadvertising.com\"},{\"text\":\"SIGN UP ON RAKUTEN\",\"url\":\"https:\\/\\/rakutenadvertising.com\"}]}]}', 1, '2026-09-24 15:48:38'),
(3, 'bra-size-guide', 'Bra Size Guide', '{\"hero\":{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784563234\\/bra-size\\/nqw6rluehzfq8kzdlzmh.jpg\",\"headingLine1\":\"find your\",\"headingItalic\":\"bra\",\"headingLine2\":\"size\",\"description\":\"Are you wearing the right size? What size are you in Underpure? Finding the right bra can be hard, but we\'re here to help. Let us get you the support you need.\",\"buttonText\":\"GET STARTED\"},\"navTabs\":[{\"label\":\"Find Your Bra Size\",\"anchor\":\"find-size\"},{\"label\":\"Bra Style Guide\",\"anchor\":\"style-guide\"},{\"label\":\"Get Support\",\"anchor\":\"support\"},{\"label\":\"Schedule A Fitting\",\"anchor\":\"fitting\"},{\"label\":\"Sister Sizing\",\"anchor\":\"sister-sizing\"}],\"intro\":{\"heading\":\"before we get\",\"headingItalic\":\"started...\",\"description\":\"Start by standing in front of a mirror wearing your best-fitting, non-padded underwire bra. You\'ll also need a soft measuring tape. Remember to measure in inches.\"},\"sections\":[{\"headingPrefix\":\"the\",\"headingItalic\":\"band\",\"anchor\":\"the-band\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784563362\\/bra-size\\/ctrvhbvt6ju4n4ff68sz.jpg\",\"imageAlt\":\"Measuring the band\",\"paragraphs\":[\"Your bra\'s band provides most of its support (not the straps!) Most women are wearing a band that\'s too loose.\"],\"steps\":[\"With a measuring tape, measure below your bust, directly below the wire of your bra.\",\"Ensure the tape is parallel to the floor, i.e at the same level on your back, sides and front.\",\"Enter this number in the \\\"band measurement\\\" box below.\"],\"hotTip\":\"In between numbers? Round to the nearest whole number.\"},{\"headingPrefix\":\"the\",\"headingItalic\":\"bust\",\"anchor\":\"the-bust\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784563636\\/bra-size\\/iyagras08pzl8ctr29zk.jpg\",\"imageAlt\":\"Measuring the bust\",\"paragraphs\":[],\"steps\":[\"Loop the measuring tape around your back, just under your shoulder blades to measure around the fullest part of your bust.\",\"Keep the measuring tape level from end to end, ensuring it is close, but not too tight, to find a comfortable and snug position.\",\"Enter this number in the \\\"bust measurement\\\" box below.\"],\"hotTip\":\"If the measurement falls on the half inch, round it up!\"}],\"calculator\":{\"headingPrefix\":\"your\",\"headingItalic\":\"Underpure\",\"headingSuffix\":\"size\",\"description\":\"Our products may vary in size from your universal sizing. Use the calculator below to determine your best fitting Underpure sizes.\",\"bandPlaceholder\":\"Band measurement\",\"bustPlaceholder\":\"Bust measurement\",\"buttonText\":\"GET MY SIZE\",\"resultMessage\":\"Our collection is the best fit for your range.\",\"shopButtons\":[{\"label\":\"SHOP BRAS\",\"url\":\"\\/collection\"}],\"note\":\"All sizes in inches\"},\"extraSections\":[{\"anchor\":\"style-guide\",\"headingPrefix\":\"bra\",\"headingItalic\":\"style guide\",\"description\":\"Not sure which style is right for you? Explore our core silhouettes.\",\"items\":[{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784563779\\/bra-size\\/mm0rgdxscushioyfr0bd.jpg\",\"title\":\"The Demi\",\"description\":\"A classic half-cup silhouette that offers medium coverage and natural lift.\"},{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784563960\\/bra-size\\/ky6utda1leny4jgbxqmh.jpg\",\"title\":\"The Balconette\",\"description\":\"Features wider set straps and a sweetheart neckline for beautiful framing.\"},{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784564110\\/bra-size\\/lf6ywlg0rchh9n4zf2ka.jpg\",\"title\":\"The Triangle\",\"description\":\"Wire-free comfort with natural shape, perfect for smaller busts.\"},{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784564255\\/bra-size\\/wn3sllk1t6pumrdklrjh.jpg\",\"title\":\"The Plunge\",\"description\":\"Deep V-neckline ideal for low-cut tops, creating beautiful cleavage.\"},{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784564213\\/bra-size\\/ee7lshaaldup2x7i7db6.png\",\"title\":\"The Longline\",\"description\":\"Extended band for smoothing and support, doubles as a crop top.\"},{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784564194\\/bra-size\\/g1lhxt7yaasa6vjyepue.png\",\"title\":\"The Strapless\",\"description\":\"Versatile support without the straps, essential for bare-shoulder looks.\"},{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784564169\\/bra-size\\/c9swsdsp3pp64uxue7hk.png\",\"title\":\"The Bralette\",\"description\":\"Ultimate soft comfort for everyday lounging and layering.\"},{\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784564149\\/bra-size\\/pihr1dzdsjtybc9ijltm.jpg\",\"title\":\"The Push-Up\",\"description\":\"Maximum lift and enhancement for when you want extra volume.\"}]}],\"fitSection\":{\"description\":\"Band too tight or straps sliding off your shoulders? Get schooled on all things bra fit & sister sizing below.\",\"buttonText\":\"BRA FIT 101\",\"buttonUrl\":\"\\/\"},\"supportSection\":{\"headingPrefix\":\"we\",\"headingItalic\":\"support you\",\"description\":\"Still need help? Chat with a Underpure stylist for more information, or book an in-store fitting with a bra specialist below (we recommend a professional fitting every 6 months to a year).\",\"buttonText\":\"CHAT WITH UNDERPURE\"}}', 1, '2026-09-24 10:14:01'),
(4, 'careers', 'Careers', '{\"enabledInFooter\":false,\"title\":\"join the underpure team\",\"bottomText\":\"We\'re always looking for amazing, hard working, talented people to join our team. For general inquiries, please send your resume and portfolio to careers@underpure.com\",\"departments\":[{\"name\":\"MARKETING & E-COMMERCE\",\"jobs\":[{\"title\":\"Retention Marketing Manager\"},{\"title\":\"Ecommerce Product Coordinator\"}]},{\"name\":\"PRODUCTION\",\"jobs\":[{\"title\":\"Sample & Technical Design Assistant\"}]},{\"name\":\"RETAIL\",\"jobs\":[{\"title\":\"Boutique Manager\"}]},{\"name\":\"INTERNSHIPS\",\"jobs\":[{\"title\":\"Social Media \\/ Marketing Intern\"},{\"title\":\"Creative Intern\"},{\"title\":\"Graphic Design Intern\"},{\"title\":\"PR Intern\"},{\"title\":\"Design Intern\"}]}]}', 1, '2026-09-24 10:14:01'),
(5, 'contact-us', 'Contact Us', '{\"stores\": [], \"clientServices\": {\"title\": \"client services\", \"introText\": \"UnderPure\'s Client Services team would be happy to assist you with your online order. Contact us for fit and style advice, delivery inquiries and returns or exchanges. We\'ll even help you pick out that perfect gift.\", \"hoursText\": \"UnderPure Client Services representatives are available Monday through Friday, 10AM-6PM EST.\", \"chatText\": \"See Chat icon in lower right hand corner\", \"email\": \"hello@underpure.com\", \"phone\": \"+92 300 0000000\"}, \"otherInquiries\": {\"title\": \"other inquiries\", \"socialText\": \"Share what you love. Love what you share:\", \"socialHandle\": \"@underpurenyc\", \"socialUrl\": \"https://instagram.com/underpurenyc\", \"generalEmail\": \"hello@underpure.com\", \"pressEmail\": \"press@underpure.com\", \"wholesaleEmail\": \"wholesale@underpure.com\", \"marketingEmail\": \"press@underpure.com\"}}', 1, '2026-09-24 10:14:01'),
(6, 'cookie-declaration', 'Cookie Declaration', '{\"title\":\"Cookie Declaration\",\"metaText\":\"Date generated by System: 7\\/25\\/2026, 1:11:49 PM\",\"introText\":\"We use cookies to optimize website functionality, analyze the performance, and provide personalized experiences to you. Some cookies are essential to make the website operate and function correctly. Those cookies cannot be disabled. In this window you can manage your preference of cookies.\",\"sections\":[{\"heading\":\"Strictly necessary cookies\",\"description\":\"These cookies are essential in order to enable you to move around the website and use its features, such as accessing secure areas of the website. The website cannot function properly without these cookies.\",\"cookies\":[{\"name\":\"localization\",\"domain\":\"underpure.com\",\"retention\":\"1 year\",\"type\":\"First-party (Cookie)\",\"provider\":\"System\",\"purpose\":\"Used to localize the cart to the correct country.\"},{\"name\":\"cart_currency\",\"domain\":\"underpure.com\",\"retention\":\"2 weeks\",\"type\":\"First-party (Cookie)\",\"provider\":\"System\",\"purpose\":\"Used after a checkout is completed to initialize a new empty cart with the same currency as the one just used.\"},{\"name\":\"cart\",\"domain\":\"underpure.com\",\"retention\":\"1 month\",\"type\":\"First-party (Cookie)\",\"provider\":\"System\",\"purpose\":\"Contains information related to the user\'s cart.\"}]}]}', 1, '2026-09-24 10:14:01'),
(7, 'do-not-sell', 'Do Not Sell My Info', '{\"heading\":\"Your Privacy Rights\",\"content\":\"At UnderPure, we respect your privacy. We do not sell, rent, or trade your personal information to third parties for monetary or commercial gain.\\n\\nWe only use your data (such as your name, shipping address, and phone number) strictly to process and deliver your orders via our courier partners and to improve your shopping experience. If you have any questions or wish to update your data, feel free to reach out to us at support@underpure.com or via WhatsApp support.\"}', 1, '2026-09-24 10:14:01'),
(8, 'faqs', 'Frequently Asked Questions', '[{\"id\":1,\"category\":\"placing your order\",\"question\":\"Can I cancel or change my order?\",\"answer\":\"Orders can be cancelled within 1 hour of placement. After this window, orders enter processing and cannot be cancelled. Please contact customer service immediately if you need to cancel.\"},{\"id\":2,\"category\":\"placing your order\",\"question\":\"What payment methods do you accept?\",\"answer\":\"We currently accept Cash on Delivery (COD) for all orders across Pakistan. You can pay securely in cash when your package is delivered right to your doorstep. No advance online payment is required.\"},{\"id\":3,\"category\":\"order status\",\"question\":\"How long before my order is shipped?\",\"answer\":\"All orders are processed and dispatched promptly. Once your order is confirmed, it typically takes a total of 2 to 4 business days to reach your doorstep anywhere in Pakistan.\"},{\"id\":4,\"category\":\"order status\",\"question\":\"How can I track my order?\",\"answer\":\"Once your order has shipped, you will receive a confirmation email with a tracking number. You can also track your order by logging into your account.\"},{\"id\":5,\"category\":\"order status\",\"question\":\"An item is missing from my order, what should I do?\",\"answer\":\"We apologize for the inconvenience! Please contact us immediately with your order number via email at support@underpure.com or reach out to our support team directly on WhatsApp, and we will resolve this for you right away.\"},{\"id\":6,\"category\":\"order status\",\"question\":\"I\'ve received a faulty or incorrect item with my order.\",\"answer\":\"We sincerely apologize for this! Since we operate exclusively online, please contact us within 14 days of receiving your order by sending photos of the faulty or incorrect item to our email at support@underpure.com or message us directly on our WhatsApp support. Our team will guide you through the quick replacement or exchange process.\"},{\"id\":7,\"category\":\"shipping & delivery\",\"question\":\"How long does shipping take?\",\"answer\":\"All orders are processed and dispatched promptly. Once your order is confirmed, it typically takes a total of 2 to 4 business days to reach your doorstep anywhere in Pakistan.\"},{\"id\":8,\"category\":\"shipping & delivery\",\"question\":\"Is free shipping available?\",\"answer\":\"Yes! We offer free standard shipping on all orders across Pakistan above Rs. 5,000. For orders below this amount, standard delivery charges will apply at checkout.\"},{\"id\":9,\"category\":\"shipping & delivery\",\"question\":\"Do you ship internationally?\",\"answer\":\"Currently, we do not ship internationally. We only ship orders within Pakistan.\"},{\"id\":10,\"category\":\"returns\",\"question\":\"What is your return or exchange policy?\",\"answer\":\"Due to the intimate nature of our products and for hygiene reasons, we do not accept general returns or exchanges. However, if you received a faulty, damaged, or incorrect item, you can request an exchange within 14 days of delivery.\\n\\nTo be eligible for an exchange, the item must be unworn, unwashed, in its original condition, and with all original tags and packaging intact.\\n\\nIf you face any issue, please reach out to us via support@underpure.com or through our WhatsApp support along with photos of the item, and our team will guide you through the process.\"},{\"id\":11,\"category\":\"returns\",\"question\":\"How do I start a return or exchange?\",\"answer\":\"Since all eligible exchanges (for faulty or incorrect items) are handled online, you can easily start a request by reaching out to our support team via email at support@underpure.com or directly on our WhatsApp support. Please share your order number and photos of the item, and our team will guide you step-by-step on how to send the parcel back.\"},{\"id\":12,\"category\":\"refunds\",\"question\":\"How long does it take to process a refund?\",\"answer\":\"Once your returned item is received and inspected by our team, please allow 3 to 5 business days for processing. Since we operate on Cash on Delivery (COD), approved refunds are typically issued via Bank Transfer, EasyPaisa, or JazzCash. Our support team will coordinate with you to collect your account details.\"},{\"id\":13,\"category\":\"Shipping Protection\",\"question\":\"What does Shipping Protection cover?\",\"answer\":\"When you opt for Shipping Protection at checkout, your order is fully covered against any loss, theft, or damage during transit. If anything happens to your package on the way to your doorstep, we will promptly replace or refund it. Simply reach out to our support team via support@underpure.com or WhatsApp support with your order details\"},{\"id\":14,\"category\":\"product details & fit\",\"question\":\"How do I find my correct size?\",\"answer\":\"We recommend using our Size Guide available on every product page. For bras, you can also use our \\\"Find Your Bra Size\\\" tool.\"},{\"id\":16,\"category\":\"Store Locations\",\"question\":\"Do you have physical stores?\",\"answer\":\"We currently operate exclusively online to bring our premium collections directly to your doorstep anywhere in Pakistan. This allows us to maintain the highest standards of hygiene, quality, and direct customer care without physical store limitations.\"}]', 1, '2026-09-24 10:14:01'),
(9, 'return-policy', 'Returns & Exchange Policy', '{\"bannerImage\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784052128\\/returns\\/wa3ogd0m6fssbmannr4m.jpg\",\"introText\":\"UnderPure will accept returns on unworn merchandise with all original tags attached initiated within 30 days of your order shipping. Please note: items that have been tried on with direct skin contact which show any signs of wear will not be accepted. Signs of wear can include, but are not limited to, unhygienic or deodorant marks, pet hair, missing tags, odor or fragrance. We recommend always wearing your own underwear when first trying on your purchase.\\n\\n\\nOnce your return is delivered back to us, our team thoroughly inspects all items ensuring they are in new condition. This process can take up to 10 business days from the date your return is delivered back to us. If your return is accepted. You will receive a notification of your refund or store credit via email or WhatsApp.\\n\\nUnderPure reserves the right to refuse any return that is received worn, damaged, or does not comply with the\\naforementioned policies. In the instance that a return is received in unacceptable condition, your return will be cancelled and the item will be shipped back to you.\",\"boldPolicy1\":\"Full priced merchandise can be returned for exchange, store credit or refund. Sale items may be returned for exchange or store credit only.\",\"finalSaleText\":\"Items marked \'FINAL SALE\' are final sale and are non-returnable.\",\"feeText\":\"UnderPure charges a flat 250 PKR return fee on all returns for refund. Exchanges are subject to a 250 PKR courier charge.\",\"outsideReturnsText\":\"Returns made outside of our returns systems cannot be processed.\",\"noStoreReturnsText\":\"For more information about Returns, contact us via WhatsApp or email.\",\"buttonText\":\"INITIATE RETURN\",\"buttonLink\":\"#\",\"boutiqueReturnsText\":\"Unworn merchandise in sellable condition with all tags attached will be considered for exchange or store credit or refund within 14 days of purchase.\\n\\nAll underwear, bodysuits & accessories are final sale.\",\"euWithdrawalText\":\"You have the right to withdraw from your purchase contract within 14 days without giving any reason. To exercise your right of withdrawal, you must inform us of your decision to withdraw from the contract by an unequivocal statement (for example, by email or WhatsApp). Please send withdrawal requests to: underpure18@gmail.com\\n\\nIf you withdraw from this contract, we will process your request without undue delay. We may withhold reimbursement until we have received the goods back.\\n\\nYou must send back the goods without undue delay and in any event no later than 14 days from the day on which you communicate your withdrawal from this contract to us.\",\"withdrawalLinkText\":\"Submit Withdrawal Here\",\"withdrawalLinkUrl\":\"#\",\"withdrawalFormLink\":\"#\"}', 1, '2026-09-24 10:14:02');
