('lovelistData', '{\"pageTitle\":\"Lovelist\",\"guestUserText\":\"Guest Shopper\",\"loggedInDefaultText\":\"Logged In User\",\"tabs\":{\"lovelist\":\"Lovelist\",\"saved\":\"Saved for Later\"},\"buttons\":{\"clearList\":\"Clear List\",\"moveToCart\":\"Move all to cart\",\"addToCart\":\"ADD TO CART\",\"quickShop\":\"QUICK SHOP\"},\"emptyLovelist\":{\"title\":\"Love It? Add To My Lovelist\",\"buttonText\":\"Continue shopping\",\"link\":\"\\/\"},\"emptySaved\":{\"title\":\"No products are currently saved\",\"subtitle\":\"Save some products for later from the cart page\",\"buttonText\":\"Open Cart Page\",\"link\":\"\\/cart\"},\"recommendations\":{\"enabled\":true,\"title\":\"Selected For You, Lover\",\"mode\":\"custom\",\"customProducts\":[{\"id\":236,\"slug\":\"elite-support-sports-bra\",\"name\":\"Elite Support Sports Bra\",\"price\":\"1700.00\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1788784657\\/products\\/mozwnjsrjk2e126rtbb0.webp\"},{\"id\":231,\"slug\":\"champion-shock-absorber-multi-sports-support-bra\",\"name\":\"Champion Shock Absorber Multi Sports Support Bra\",\"price\":\"1650.00\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1788783581\\/products\\/jutiaumsvq7nr4mc3c0e.webp\"},{\"id\":227,\"slug\":\"primadonna-sport-bra\",\"name\":\"PrimaDonna Sport Bra\",\"price\":\"1400.00\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1788779927\\/products\\/ulud0lgjnmcxsxzgoblo.webp\"},{\"id\":149,\"slug\":\"panache-clara-full-cup-bra\",\"name\":\"Panache Clara Full Cup Bra\",\"price\":\"1800.00\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1787651326\\/products\\/kwdn8nxf7yrydtlyejcb.webp\"}]},\"guestPopup\":{\"title\":\"Save your list\",\"subtitle1\":\"You are currently shopping anonymously.\",\"subtitle2\":\"Either log in or save your wishlist items by entering your email address.\",\"buttonText\":\"LOG IN\"},\"sharePopup\":{\"title\":\"Login to Share your Wishlist\",\"subtitle1\":\"You are currently shopping anonymously.\",\"subtitle2\":\"Please login to share your Wishlist.\",\"buttonText\":\"LOG IN\"},\"emailShare\":{\"title\":\"Share List Via Email\",\"senderLabel\":\"Sender Name\",\"senderPlaceholder\":\"Your Full Name (optional)\",\"recipientLabel\":\"Recipients Email\",\"recipientPlaceholder\":\"shopper@example.com\",\"messageLabel\":\"Message\",\"messageDefault\":\"Hi lover. Check out my lovelist.\",\"requiredText\":\"* - Required Fields\",\"buttonText\":\"SHARE LIST\",\"orShareVia\":\"Or share via\",\"copyLink\":\"Copy Link\",\"facebook\":\"Facebook\",\"twitter\":\"Twitter\"}}'),
('loyaltyData', '{\"heroImage\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1783422225\\/loyalty\\/xvysksrsado0cxq9wv7x.png\",\"faqBannerImage\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784558117\\/loyalty\\/lobdode66wmqvwr7xobg.jpg\",\"heroTitle\":\"UnderPure with benefits\",\"heroSubtitle\":\"Join our loyalty program to access exclusive benefits every time you shop. The more you spend, the better your benefits. Earn one UPCoin for every PKR spent. Create an account now to start earning rewards.\",\"faqTitle\":\"got questions?\",\"tiers\":[{\"id\":1,\"tier\":\"tier 1\",\"subtitle\":\"enrolled on creation\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784557080\\/loyalty\\/i7gjorxxbbsj7xbvri07.jpg\",\"benefits\":[\"Free standard shipping on all Pakistan orders (Rs. 5000+)\",\"Early access to new collections and seasonal launches\"]},{\"id\":2,\"tier\":\"tier 2\",\"subtitle\":\"500 UPCoins\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784557856\\/loyalty\\/iaupy9yigqvnjpbozmhl.jpg\",\"benefits\":[\"Plus, 20% off during your birthday month\",\"Double UPCoin events for select collections\",\"Free 30-day returns\",\"Free standard shipping on all Pakistan orders (Rs. 5000+)\",\"Early access to new collections and seasonal launches\"]},{\"id\":3,\"tier\":\"tier 3\",\"subtitle\":\"1500 UPCoins\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784557731\\/loyalty\\/oplr4dg3vrwsn4zqyxew.jpg\",\"benefits\":[\"Annual Exclusive Gift Box\",\"Plus, 20% off during your birthday month\",\"Double UPCoin events for select collections\",\"Free 30-day returns\",\"Free standard shipping on all Pakistan orders Rs. 5000+\",\"Early access to new collections and seasonal launches\"]},{\"id\":4,\"tier\":\"tier 4\",\"subtitle\":\"3000 UPCoins\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784557188\\/loyalty\\/nospvto2rbwvi0x7rnx4.jpg\",\"benefits\":[\"Annual Exclusive Gift Box\",\"Priority Concierge WhatsApp Support\",\"Free 2-day shipping on all Pakistan orders\",\"Free returns\",\"Plus, 20% off during your birthday month\",\"Free 30-day returns\",\"Double UPCoin events for select collections\",\"Early \'Bird\' launch access (24 hours before others)\"]},{\"id\":5,\"tier\":\"tier 5\",\"subtitle\":\"The Pure Inner Circle 50000 UPCoins\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1784557283\\/loyalty\\/wwk99gt3r7k5ez1lhbwx.jpg\",\"benefits\":[\"Lifetime VIP Status (25% off all orders)\",\"Annual Bespoke Premium UnderPure Gift Box (exclusive curated experience)\",\"Dedicated Direct WhatsApp Support Line (priority 24\\/7 access)\",\"Free 2-day shipping on all Pakistan orders\",\"Free returns\",\"Plus, 20% off during your birthday month\",\"Free 30-day returns\",\"Double UPCoin events for select collections\",\"Early \'Bird\' launch access (24 hours before others)\"]}],\"faqs\":[{\"id\":1,\"q\":\"How do I join?\",\"a\":\"Customers can join the loyalty program by creating an account on our website. Joining is free!\"},{\"id\":2,\"q\":\"What is a UPCoin?\",\"a\":\"UPCoins are points you earn on every purchase. Rs. 1 spent = 1 UPCoin.\"},{\"id\":3,\"q\":\"When does my loyalty tier reset?\",\"a\":\"Your tier status is valid for a rolling 12-month period from the date you enter the tier.\"},{\"id\":4,\"q\":\"How do I redeem my birthday discount?\",\"a\":\"Make sure your birthday is entered in your account profile. You will receive an email with your unique code on your birthday.\"},{\"id\":5,\"q\":\"How do I sign up for a fit or style consultation?\",\"a\":\"As a member, you can reach out to our concierge team at UnderPure@UnderPuredumal.com to schedule your virtual or in-person consultation.\"},{\"id\":6,\"q\":\"How will I be given early access to seasonal sales and launches?\",\"a\":\"You will receive exclusive email invitations before sales and launches open to the general public.\"},{\"id\":7,\"q\":\"How can I access 15% off duty early or double UPCoin events?\",\"a\":\"Keep an eye on your email inbox! We will notify members when these special events are happening.\"},{\"id\":8,\"q\":\"How do I redeem free 2-day shipping on all orders?\",\"a\":\"Once you reach Tier 4 or 5, the free 2-day shipping option will automatically appear at checkout when logged into your account.\"},{\"id\":9,\"q\":\"Will dollars spent prior to UnderPure Insider sign up count towards my tier total?\",\"a\":\"Unfortunately, no. You must have an active account at the time of purchase to earn UPCoins.\"},{\"id\":10,\"q\":\"When will my new purchase be reflected on the loyalty page?\",\"a\":\"Points typically appear in your account 14 days after your order has shipped.\"},{\"id\":11,\"q\":\"What items can be monogrammed, and how do I redeem this service?\",\"a\":\"Select silk items are eligible for monogramming. Tier 4 and 5 members can contact concierge to arrange this service.\"},{\"id\":12,\"q\":\"What is VIP client concierge?\",\"a\":\"A dedicated team member will be available via phone or email to assist you with styling, priority pre-orders, and personalized gifting.\"}],\"faqBannerTitle\":\"Underpure with benefits\"}'),
('loyaltySettings', '{\"signupBonus\":500,\"pointsPerSpend\":100,\"spendUnit\":1000,\"redemptionRatio\":0.1,\"birthdayBonus\":350,\"tier2Threshold\":500,\"tier3Threshold\":1000,\"tier4Threshold\":2000,\"tier5Threshold\":5000}'),
